import {demo,calculate,validate,convertPlan,countdown,lean,fat,barista,coast,goalCost,goalPlan,requiredCorpus,assetClasses,regions,blendedReturn,yearFlows,stressTest,simulate,legacyAt,readiness} from './engine.js?v=dev';
const $=id=>document.getElementById(id),KEY='fire-planner-v1',currencies=['INR','USD','EUR','GBP','AED','CAD','AUD','SGD','JPY'];
const date=new Date();date.setFullYear(date.getFullYear()+demo.retire-demo.age);const defaultDate=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const initial=()=>({plan:structuredClone(demo),currency:'INR',snapshots:[],targetDate:defaultDate,theme:'sunrise',personal:false});let state=initial(),persistent=false,basis='nominal',formValid=true,timer;
// Checks saved or imported data before it replaces the current plan.
function checkState(s){if(!s||typeof s!=='object')throw Error();validate(s.plan);if(!currencies.includes(s.currency)||!Array.isArray(s.snapshots)||s.snapshots.length>5||!countdown(s.targetDate)||!['sunrise','ocean','night'].includes(s.theme))throw Error();s.snapshots.forEach(x=>{validate(x.plan);if(typeof x.name!=='string')throw Error();});return {plan:s.plan,currency:s.currency,snapshots:s.snapshots,targetDate:s.targetDate,theme:s.theme,personal:s.personal!==false};}
try{const raw=localStorage.getItem(KEY);if(raw){state=checkState(JSON.parse(raw));persistent=true;}}catch{setTimeout(()=>toast('Saved data could not be loaded. Showing a sample without overwriting it.'),100);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function money(n){if(n===null||!Number.isFinite(n))return '—';if(state.currency==='INR'&&Math.abs(n)>=1e5)return `${n<0?'−':''}₹${(Math.abs(n)/(Math.abs(n)>=1e7?1e7:1e5)).toFixed(2)} ${Math.abs(n)>=1e7?'Cr':'L'}`;return new Intl.NumberFormat(state.currency==='INR'?'en-IN':'en-US',{style:'currency',currency:state.currency,maximumFractionDigits:0,...(Math.abs(n)>=1e6?{notation:'compact',maximumFractionDigits:2}:{})}).format(n);}
// Amount inputs are grouped as you type: 1,80,000 for rupees, 180,000 for other currencies.
const MONEY=new Set(['legacy','assets','income','expenses','contribution','pension','leanExpenses','fatExpenses','baristaIncome']);
const groupInt=d=>d?BigInt(d).toLocaleString(state.currency==='INR'?'en-IN':'en-US'):'';
const currencySymbol=()=>state.currency==='INR'?'₹':new Intl.NumberFormat('en-US',{style:'currency',currency:state.currency}).formatToParts(0).find(x=>x.type==='currency').value;
const amountWrap=input=>{const sym=currencySymbol();return `<span class="amount-field" style="--sym:${sym.length}ch"><span class="amount-symbol" aria-hidden="true">${esc(sym)}</span>${input}</span>`;};
function fmtAmount(n){const [i,d]=String(Number(n.toFixed(2))).split('.');return groupInt(i)+(d?'.'+d:'');}
// Shorthand units people type: 60L, 60 lakh, 1.5cr, 45k, 1.2m, 2bn. Commas, spaces and symbols are ignored.
const UNITS={l:1e5,lac:1e5,lacs:1e5,lakh:1e5,lakhs:1e5,cr:1e7,crs:1e7,crore:1e7,crores:1e7,k:1e3,thousand:1e3,m:1e6,mn:1e6,million:1e6,b:1e9,bn:1e9,billion:1e9};
function amountValue(v){const m=String(v).toLowerCase().replace(/[,\s₹$€£¥]/g,'').match(/^(\d+(?:\.\d+)?|\.\d+)([a-z]*)$/);if(!m||(m[2]&&!(m[2] in UNITS)))return null;return Math.round(Number(m[1])*(m[2]?UNITS[m[2]]:1)*100)/100;}
const unitExample=()=>state.currency==='INR'?'60L or 1.5cr':'45k or 1.2m';
function parseAmount(v,min,max){const n=amountValue(v);if(n===null)throw Error(`Enter a number, or a shorthand like ${unitExample()}.`);if(n<min||n>max)throw Error('Complete each field within its allowed range.');return n;}
function amountHint(i,text){const host=i.closest('.amount-field')||i;let h=host.nextElementSibling;if(!h?.classList.contains('amount-hint')){if(!text)return;h=document.createElement('span');h.className='amount-hint';h.setAttribute('aria-live','polite');host.after(h);}h.textContent=text;h.hidden=!text;}
function liveFormat(i){const v=i.value;if(/[a-z]/i.test(v)){const n=amountValue(v);amountHint(i,n===null?`Try ${unitExample()}`:`= ${currencySymbol()} ${fmtAmount(n)}`);return;}amountHint(i,'');const pos=i.selectionStart??v.length,keep=v.slice(0,pos).replace(/[^\d.]/g,'').length,c=v.replace(/[^\d.]/g,''),dot=c.indexOf('.'),int=(dot<0?c:c.slice(0,dot)).replace(/^0+(?=\d)/,''),out=groupInt(int)+(dot<0?'':'.'+c.slice(dot+1).replace(/\./g,'').slice(0,2));if(out===v)return;i.value=out;let n=0,p=0;while(p<out.length&&n<keep){if(/[\d.]/.test(out[p]))n++;p++;}i.setSelectionRange(p,p);}
document.addEventListener('input',e=>{if(e.target.matches?.('input[data-money]'))liveFormat(e.target);},true);
document.addEventListener('focusout',e=>{if(e.target.matches?.('input[data-money]')){const n=amountValue(e.target.value);if(n!==null){e.target.value=fmtAmount(n);amountHint(e.target,'');}}});
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,4500);}
function persist(){if(persistent)try{localStorage.setItem(KEY,JSON.stringify(state));$('save-status').textContent='Saved on this browser';}catch{persistent=false;$('persist').checked=false;$('save-status').textContent='Not saved';toast('Storage unavailable. Your plan remains in this session.');}else $('save-status').textContent='Session only';saveUI();}
function saveUI(){const b=$('save-btn');b.textContent=persistent?'✓ Saved':'Save';b.classList.toggle('primary',!persistent);b.classList.toggle('secondary',persistent);b.title=persistent?'Changes save automatically on this browser':'Keep this plan on this browser';}
function commit(){state.personal=true;persist();}
const pages={overview:['A little closer to freedom.','See where you stand. Shape what comes next.','Overview'],plan:['Build your freedom plan.','Small adjustments today. More possibilities tomorrow.','Retirement plan'],goals:['A full life, thoughtfully planned.','Make room for the milestones that matter.','Life goals'],compare:['Find the path that feels right.','Compare possibilities before changing your plan.','Compare plans'],countdown:['Your next chapter is coming.','Keep the future you’re working toward in sight.','Countdown'],stress:['Prepare for a bumpy road.','See how your plan holds up when markets don’t move in a straight line.','Stress test'],settings:['Make yourself at home.','Your currency, your preferences, your privacy.','Settings']};
function navigate(v){if(!pages[v])v='overview';document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('[data-view]').forEach(e=>{e.classList.toggle('active',e.dataset.view===v);if(e.closest('nav')){if(e.dataset.view===v)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');}});['page-title','subtitle','breadcrumb'].forEach((id,i)=>$(id).textContent=pages[v][i]);history.replaceState(null,'','#'+v);if(v==='stress')renderStress();if(typeof syncIntro==='function')syncIntro();{const n=document.querySelector('nav'),a=n.querySelector('[aria-current]');if(a&&n.scrollWidth>n.clientWidth)n.scrollLeft+=a.getBoundingClientRect().left-n.getBoundingClientRect().left-(n.clientWidth-a.offsetWidth)/2;}window.scrollTo(0,0);}
document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>navigate(e.dataset.view));window.onhashchange=()=>navigate(location.hash.slice(1));$('edit-plan').onclick=()=>navigate('plan');$('start-plan').onclick=()=>{navigate('plan');$('input-name').focus();};
// Introduction for first-time visitors: shown on the sample plan until dismissed (remembered on this device).
const INTRO_KEY='fire-planner-intro-dismissed';let introDismissed=false;try{introDismissed=localStorage.getItem(INTRO_KEY)==='1';}catch{}
function syncIntro(){const show=!state.personal&&!introDismissed;$('intro').hidden=!show;$('demo-banner').hidden=state.personal||(show&&!$('overview').hidden);}
$('intro-start').onclick=()=>{navigate('plan');$('input-name').focus();$('input-name').select();};
$('intro-dismiss').onclick=()=>{introDismissed=true;try{localStorage.setItem(INTRO_KEY,'1');}catch{}syncIntro();};
$('show-intro').onclick=()=>{introDismissed=false;try{localStorage.removeItem(INTRO_KEY);}catch{}navigate('overview');$('intro').hidden=false;$('demo-banner').hidden=true;};
function countHTML(){const c=countdown(state.targetDate);if(!c)return 'Choose a retirement date';if(c.past)return '<strong>Your chosen date has arrived.</strong>';return ['years','months','days'].map((k,i)=>`${i?'<div class="countdown-divider"></div>':''}<div class="countdown-unit"><strong>${String(c[k]).padStart(2,'0')}</strong><small>${k}</small></div>`).join('');}
// Plain-language reading of the plan. Each entry: [tone, title, explanation, bottom line (may contain <b>)].
function observations(p,r){const obs=[],yrs=p.retire-p.age,life=p.horizon-p.retire,retBal=r.projection.retirementAssets,inf=(1+p.inflation/100)**yrs,age=a=>a===null?'not reached':a;
if(r.gap<=0.5)obs.push(['good','Retirement is funded on these assumptions',`Your investments are projected to grow to ${money(retBal)} by age ${p.retire}. That covers the ${money(r.target)} needed to pay for ${life} years of retirement.`,`Surplus at retirement: <b>${money(retBal-r.target)}</b>.${r.forecast!==null&&r.forecast<p.retire?` That head start means you could retire as early as <b>${r.forecast}</b>.`:''}`]);
else{const fs=r.projection.firstShortfall;obs.push([fs!==null&&fs<p.retire+15?'bad':'warn',`A ${money(r.gap)} gap at retirement`,`By age ${p.retire} your investments are projected to reach ${money(retBal)}, short of the ${money(r.target)} needed.${fs!==null?` On this path the money runs out at age ${fs}.`:''}`,r.requiredMonthly===null?'Your target age is today, so only a lower spending level or a later target can close it.':`Investing <b>${money(r.requiredMonthly)}/mo</b> (${money(r.requiredMonthly-p.contribution)} more than now) closes it${r.forecast!==null?`, or keep investing as you are and retire at <b>${r.forecast}</b>`:''}.`]);}
const c=coast(p);if(c){if(c.reached)obs.push(['good','You’ve already reached Coast FIRE',`Your ${money(p.assets)} would grow to fund retirement at ${p.retire} even if you never invested again.`,'Everything you invest from now on builds a surplus or brings retirement forward.']);
else if(c.age!==null)obs.push(['good',`Coast point reached at age ${c.age}`,`From age ${c.age}, the ${money(c.balance)} you’ll have invested grows to your FIRE number by ${p.retire} with no further investing.`,`Everything invested after ${c.age} builds surplus rather than closing the gap.`]);
else obs.push(['warn','No coast point on this plan',`Even investing every month until ${p.retire}, the portfolio doesn’t reach what retirement needs, so there is no age at which you could stop.`,`You’d need <b>${money(c.todayNumber)}</b> invested today to coast. You have ${c.progress.toFixed(0)}% of that.`]);}
if(yrs>0){const step=10**Math.round(Math.log10(p.expenses))/10,per=requiredCorpus({...p,expenses:p.expenses+step})-r.target,lower=Math.max(step,Math.round(p.expenses*0.9/step)*step),reqLower=requiredCorpus({...p,expenses:lower});
obs.push(['info',`Every ${money(step)}/mo of spending needs ${money(per)} of corpus`,`Each month’s spending grows with ${p.inflation}% inflation for ${yrs} years and is then paid for ${life} years, so spending moves your target more than anything else.`,`At ${money(lower)}/mo instead of ${money(p.expenses)}, the requirement falls to <b>${money(reqLower)}</b>, which is ${money(r.target-reqLower)} less.`]);
obs.push(['info',inf>=2?'Inflation more than doubles your costs':`Inflation raises your costs by ${Math.round((inf-1)*100)}%`,`At ${p.inflation}% a year, the ${money(p.expenses)} you spend each month today will cost ${money(p.expenses*inf)} a month by age ${p.retire}. Targets on this page are in future money unless marked otherwise.`,`Your ${money(r.target)} target is worth <b>${money(r.todayTarget)}</b> in today’s money.`]);}
const f=yearFlows(p,p.retire),spend=f.spend*(1/(1-p.withdrawalTax/100));if(r.target>0&&spend>0){const rate=spend/r.target*100,real=((1+p.postReturn/100)/(1+p.inflation/100)-1)*100;
obs.push([rate<=3.5?'good':rate<=4.5?'warn':'bad',`A ${rate.toFixed(1)}% first-year withdrawal`,`In your first year of retirement you’d take out ${money(spend)}${p.withdrawalTax?` including ${p.withdrawalTax}% tax`:''}, which is ${rate.toFixed(1)}% of the ${money(r.target)} target. ${rate<=4?'That is at or below':'That is above'} the often-quoted 4% rule of thumb, which assumes a 30-year retirement; yours runs ${life} years.`,`The plan relies on ${p.postReturn}% returns after retirement against ${p.inflation}% inflation, a real return of <b>${real.toFixed(1)}%</b> a year.`]);}
if(p.income>0){const sur=r.surplus;if(p.contribution>sur)obs.push(['bad','Planned investing exceeds your surplus',`You plan to invest ${money(p.contribution)} a month, but only ${money(Math.max(0,sur))} is left after ${money(p.expenses)} of spending from ${money(p.income)} income.`,'Raise income, trim spending or lower the monthly investment, otherwise this projection is optimistic.']);
else obs.push(['good',`${Math.round(p.contribution/sur*100)}% of your surplus goes to retirement`,`Of the ${money(sur)} left after spending each month, ${money(p.contribution)} is invested for retirement.`,`The other <b>${money(sur-p.contribution)}</b> is free for goals, emergencies or investing more.`]);}
const goals=p.goals.filter(g=>g.kind!=='in'),shared=goals.filter(g=>!g.fund?.separate),own=goals.filter(g=>g.fund?.separate).map(g=>[g,goalPlan(p,g)]),short=own.filter(([,x])=>x.shortfall>0.5);
if(shared.length){const base=calculate({...p,goals:p.goals.filter(g=>g.fund?.separate||g.kind==='in')}),extra=r.requiredMonthly!==null&&base.requiredMonthly!==null?r.requiredMonthly-base.requiredMonthly:null;
obs.push(['info',`${shared.length} goal${shared.length>1?'s':''} paid from your retirement portfolio`,shared.map(g=>`${esc(g.name)}: ${money(goalCost(p,g))} at age ${g.age}`).join(' · '),extra===null?'Paid from the same savings as your retirement.':`${shared.length>1?'Together they add':'It adds'} <b>${money(Math.max(0,extra))}/mo</b> to what retirement needs${base.forecast!==r.forecast&&base.forecast!==null?`, and move your earliest retirement from ${base.forecast} to ${age(r.forecast)}`:''}.`]);}
if(short.length){const need=short.reduce((s,[,x])=>s+(x.monthlyNeeded===null?0:x.monthlyNeeded*x.shortfall/Math.max(x.gap,1e-9)),0);
obs.push(['warn',`${short.length} goal${short.length>1?'s':''} not yet funded`,short.map(([g,x])=>`${esc(g.name)}: ${money(x.shortfall)} short in ${x.years} yrs`).join(' · '),`${short.length>1?'They need':'It needs'} <b>${money(need)}/mo</b> more${short.length>1?' together':''}${r.requiredMonthly!==null?`, on top of ${money(r.requiredMonthly)}/mo for retirement`:''}.`]);}
else if(own.length)obs.push(['good',`${own.length} separately funded goal${own.length>1?'s are':' is'} on track`,own.map(([g])=>esc(g.name)).join(' · '),'Their own savings and contributions cover them without touching retirement.']);
return obs.map(([t,h,d,b])=>`<div class="obs ${t}"><strong>${h}</strong><p>${d}</p><p class="obs-bottom">${b}</p></div>`).join('');}
// Retirement readiness checklist (free). Answers live in plan.readiness so they travel with plan data.
const READY={funded:['Funded by your target age',(v,p)=>v!==null&&v<=p.retire?`You could retire from ${v}.`:`Not funded by ${p.retire} yet${v!==null?`; funded from ${v}`:''}.`],
withdrawal:['A sustainable first-year withdrawal',v=>v===null?'Not applicable.':`${v.toFixed(1)}% of your target in the first year; 4% or less is the usual guide.`],
stress:['Holds up in rough markets',v=>`Lasts in ${Math.round(v*100)}% of 200 random futures; aim for 80% or more.`],
emergency:['An emergency reserve outside your investments',v=>v===null?'How many months of spending do you keep in cash?':`${v} month${v===1?'':'s'} of spending; 6 or more is a common guide.`],
highInterestDebt:['No high-interest debt','Credit cards and personal loans cost more than investments usually earn.'],
bridgeCovered:['Money you can reach before locked accounts open','EPF, PPF, NPS or a 401k may be locked until 58–60. Do you have enough outside them for the early years?'],
healthCover:['Health cover for retirement','Insurance that does not depend on your employer.'],
upcomingCosts:['Big costs around retirement are in your plan',v=>`A home, children’s education or a car due near retirement. ${v?`${v} goal${v===1?'':'s'} planned within 5 years of retiring.`:'No goals planned near retirement yet.'}`],
willAndNominees:['A will and current nominees','So your savings reach the people you choose.']};
const READY_Q={highInterestDebt:'Do you have high-interest debt?',bridgeCovered:'Covered?',healthCover:'Arranged?',upcomingCosts:'Added?',willAndNominees:'In place?'};
function renderReadiness(p){let items;try{items=readiness(p);}catch{return;}const a=p.readiness||{},done=items.filter(i=>i.status==='done').length;
$('ready-score').textContent=`${done} of ${items.length} ready`;
$('ready-list').innerHTML=items.map(i=>{const [title,d]=READY[i.id],detail=typeof d==='function'?d(i.value,p):d,icon=i.status==='done'?'✓':i.status==='todo'?'!':'?';
let ask='';if(i.id==='emergency')ask=`<label class="ready-ask">Months<input type="number" min="0" max="120" step="1" data-ready-months value="${a.emergencyMonths??''}" placeholder="0"></label>`;
else if(READY_Q[i.id])ask=`<div class="ready-ask" role="group" aria-label="${esc(READY_Q[i.id])}"><span>${esc(READY_Q[i.id])}</span><button type="button" data-ready="${i.id}" data-val="true" class="${a[i.id]===true?'on':''}">Yes</button><button type="button" data-ready="${i.id}" data-val="false" class="${a[i.id]===false?'on':''}">No</button></div>`;
return `<div class="ready-item ${i.status}"><span class="ready-icon" aria-label="${i.status==='done'?'Ready':i.status==='todo'?'Needs attention':'Not answered'}">${icon}</span><div><strong>${esc(title)}</strong><p>${esc(detail)}</p>${ask}</div></div>`;}).join('');
document.querySelectorAll('[data-ready]').forEach(b=>b.onclick=()=>setReadiness({[b.dataset.ready]:b.dataset.val==='true'}));
const m=document.querySelector('[data-ready-months]');if(m)m.onchange=()=>setReadiness({emergencyMonths:m.value===''?undefined:Math.max(0,Math.min(120,Math.round(Number(m.value))))});}
function setReadiness(change){const next=structuredClone(state.plan),r={...(next.readiness||{}),...change};for(const k of Object.keys(r))if(r[k]===undefined)delete r[k];next.readiness=r;try{validate(next);state.plan=next;commit();render();}catch(e){toast(e.message);}}
function vsFull(age,full){if(age===null)return 'Not reached within your horizon';if(full===null)return 'Reachable, unlike your full plan';const d=full-age;return d>0?`${d} year${d>1?'s':''} sooner than your full plan`:d<0?`${-d} year${d<-1?'s':''} later than your full plan`:'Same age as your full plan';}
// Compact lifestyle table. Multiples are against your plan's yearly spending at retirement, so rows compare directly.
function renderFireTypes(p,r){const l=lean(p),f=fat(p),b=barista(p),c=coast(p),age=a=>a===null?'not reached':'age '+a,mo=v=>v===null?'—':money(v),atRet=p.expenses*12*(1+p.inflation/100)**(p.retire-p.age),x=t=>(t/atRet).toFixed(1)+'×';
const row=(name,badge,value,tip,main=false)=>`<div class="snap-row${main?' main':''}"><span class="snap-name">${name}<span class="snap-badge">${badge}</span><button type="button" class="info-btn" data-tip="${esc(tip)}" aria-label="${esc(name+': '+tip)}">i</button></span><strong>${value}</strong></div>`;
const scen=(s,label)=>`${label}. Needed at age ${p.retire}: ${money(s.target)} (${money(s.todayTarget)} in today’s money). Earliest retirement: ${age(s.forecast)}. Monthly investment to retire at ${p.retire}: ${mo(s.requiredMonthly)}. ${vsFull(s.forecast,r.forecast)}.`;
$('fire-snapshot').innerHTML=line('Yearly spending today',money(p.expenses*12))+line(`Yearly spending at age ${p.retire}`,money(atRet))+'<div class="snap-label">CORPUS BY LIFESTYLE</div>'
+row('Lean FIRE',x(l.target),money(l.target),scen(l,`A frugal budget of ${money(l.expenses)} a month`))
+row('FIRE',x(r.target),money(r.target),`Your plan at ${money(p.expenses)} a month. Needed at age ${p.retire}: ${money(r.target)} (${money(r.todayTarget)} in today’s money). Projected retirement: ${age(r.forecast)}. Monthly investment needed: ${mo(r.requiredMonthly)}.`,true)
+row('Fat FIRE',x(f.target),money(f.target),scen(f,`A generous budget of ${money(f.expenses)} a month`))
+row('Barista FIRE',x(b.target),money(b.target),scen(b,`Part-time income of ${money(b.income)} a month until age ${b.until} covers some spending`))
+(c?row('Coast FIRE',c.progress.toFixed(0)+'%',money(c.todayNumber),`Invested today, this amount grows to fund retirement at ${p.retire} with no further contributions. You have ${c.progress.toFixed(1)}% of it. ${c.reached?'You could stop investing today.':c.age===null?'Not reached on your current plan.':`You reach it at age ${c.age}, with ${money(c.balance)} invested; after that your income only needs to cover everyday spending.`}`):'');}
// One shared tooltip for every info button: hover or focus on desktop, tap on touch.
const tipEl=document.createElement('div');tipEl.className='info-tip';tipEl.setAttribute('role','tooltip');tipEl.hidden=true;document.body.append(tipEl);let tipFor=null;
function showTip(b){tipFor=b;tipEl.textContent=b.dataset.tip;tipEl.hidden=false;const r=b.getBoundingClientRect(),w=tipEl.offsetWidth,h=tipEl.offsetHeight;tipEl.style.left=Math.max(8,Math.min(document.documentElement.clientWidth-w-8,r.left+r.width/2-w/2))+'px';tipEl.style.top=(r.top-h-8<8?r.bottom+8:r.top-h-8)+'px';}
function hideTip(){tipEl.hidden=true;tipFor=null;}
document.addEventListener('pointerover',e=>{const b=e.target.closest?.('.info-btn');if(b&&e.pointerType==='mouse')showTip(b);});
document.addEventListener('pointerout',e=>{if(e.target.closest?.('.info-btn')&&e.pointerType==='mouse')hideTip();});
document.addEventListener('focusin',e=>{if(e.target.matches?.('.info-btn'))showTip(e.target);});
document.addEventListener('focusout',e=>{if(e.target.matches?.('.info-btn'))hideTip();});
document.addEventListener('click',e=>{const b=e.target.closest?.('.info-btn');if(b){tipFor===b&&!tipEl.hidden?hideTip():showTip(b);}else if(tipFor)hideTip();});
addEventListener('scroll',()=>{if(tipFor)hideTip();},{passive:true});
const line=(a,b)=>`<div class="summary-line"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`;
