const groups=[['About your plan',[['name','Plan name','text'],['age','Current age','number',18,99],['retire','Target retirement age','number',18,100],['horizon','Plan through age','number',19,110]]],['Your money today',[['assets','Retirement investments','number',0,1e12],['income','Monthly take-home income','number',0,1e9],['expenses','Monthly spending, today','number',1,1e9],['contribution','Monthly retirement investment','number',0,1e9]]],['Growth & inflation',[['inflation','Annual inflation (%)','number',0,20],['preReturn','Return before retirement (%)','number',-10,25],['postReturn','Return after retirement (%)','number',-10,20],['stepUp','Annual investment increase (%)','number',0,20],['volatility','Return volatility (%)','number',0,40]]],['Retirement income',[['pension','Monthly pension / other income, today','number',0,1e9],['pensionAge','Income starts at age','number',18,110],['withdrawalTax','Tax on withdrawals (%)','number',0,50],['legacy','Leave behind at the end (legacy)','number',0,1e12]]],['FIRE milestones',[['leanExpenses','Lean monthly spending, today','number',1,1e9],['fatExpenses','Fat monthly spending, today','number',1,1e9],['baristaIncome','Part-time monthly income, today','number',0,1e9],['baristaUntil','Part-time work until age','number',18,110]]]];
function renderForm(){formValid=true;$('form-error').textContent='';$('plan-fields').innerHTML=groups.map(([heading,fields])=>`<h3 class="field-heading">${heading}</h3><div class="form-grid">${fields.map(([k,label,type,min,max])=>`<label for="input-${k}">${label}${MONEY.has(k)?amountWrap(`<input id="input-${k}" name="${k}" type="text" inputmode="decimal" autocomplete="off" data-money value="${esc(fmtAmount(state.plan[k]))}" required>`):`<input id="input-${k}" name="${k}" type="${type}" value="${esc(type==='number'?Number(state.plan[k].toFixed(2)):state.plan[k])}" ${type==='number'?`min="${min}" max="${max}" step="${['age','retire','horizon','pensionAge','baristaUntil'].includes(k)?1:'any'}"`:'maxlength="60"'} required>`}</label>`).join('')}</div>`).join('');}
function readForm(){const next=structuredClone(state.plan);for(const[,fields]of groups)for(const[k,,type,min,max]of fields){const input=$('input-'+k);if(MONEY.has(k)){next[k]=parseAmount(input.value,min,max);continue;}if(!input.checkValidity())throw Error('Complete each field within its allowed range.');next[k]=type==='number'?Number(input.value):input.value.trim();}if(!next.name)throw Error('Enter a plan name.');return validate(next);}
