$('stress-metrics').innerHTML=`<article><div class="metric-label"><span class="metric-icon ${sr>=85?'green':sr>=60?'orange':'purple'}">◎</span>Chance of success</div><strong class="${sr>=85?'ok':sr>=60?'':'bad'}">${sr}%</strong><p>of ${st.paths.toLocaleString()} futures last through age ${p.horizon}</p></article><article><div class="metric-label"><span class="metric-icon blue">≈</span>Typical outcome</div><strong>${medOut?'Age '+medOut:money(last.p50/defl(p.horizon))}</strong><p>${medOut?'Money runs out in the median future':`Left at ${p.horizon} in the median future, today’s money`}</p></article><article><div class="metric-label"><span class="metric-icon orange">↘</span>Bad case (1 in 10)</div><strong>${badOut?'Age '+badOut:money(last.p10/defl(p.horizon))}</strong><p>${badOut?'Money runs out in the worst 10% of futures':`Still left at ${p.horizon} in the worst 10%`}</p></article><article><div class="metric-label"><span class="metric-icon green">⇄</span>Safe monthly spending</div><strong>${money(st.safeExpenses)}</strong><p>Succeeds in ${Math.round(conf*100)}% of futures · ${Math.abs(d)<1?'matches your plan':d>0?money(d)+' less than you plan':money(-d)+' more than you plan'}</p></article>`;
