$('stress-chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" tabindex="0" role="img" aria-label="Range of simulated balances from age ${p.age} to ${p.horizon}. Chance of success ${sr}%. Use arrow keys to inspect each year.">${grid}<path d="${band('p10','p90')}" fill="#efac66" fill-opacity=".16"/><path d="${band('p25','p75')}" fill="#efac66" fill-opacity=".28"/><path d="${line2('steady')}" fill="none" stroke="#86a7b4" stroke-width="1.8" stroke-dasharray="5 4"/><path d="${line2('p50')}" fill="none" stroke="#df955b" stroke-width="2.5"/><line x1="${x(p.retire)}" x2="${x(p.retire)}" y1="${T}" y2="${h-B}" stroke="#c7b69c" stroke-dasharray="4 4"/><text x="${Math.min(w-100,x(p.retire)+6)}" y="12" font-size="10" fill="#ad9370">Retire at ${p.retire}</text>${[...new Set([p.age,p.retire,Math.round((p.retire+p.horizon)/2),p.horizon])].map(a=>`<text x="${x(a)}" y="${h-10}" text-anchor="middle" fill="#a1988b" font-size="10">Age ${a}</text>`).join('')}<g class="chart-hover" visibility="hidden"><line y1="${T}" y2="${h-B}" stroke="#b9ab96"/><circle r="4.5" fill="#df955b" style="stroke:var(--cffffff)" stroke-width="2"/></g></svg><div class="chart-tip" hidden></div>`;
