$('income-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{const p=structuredClone(state.plan),s={name:String(f.get('name')).trim(),monthly:parseAmount(f.get('monthly'),1,1e9),start:Number(f.get('start')),end:Number(f.get('end')),inflate:f.get('inflate')==='on'};if(!s.name)throw Error('Enter a name.');if(!(s.end>s.start))throw Error('“Until age” must be after “From age”.');p.incomes.push(s);validate(p);state.plan=p;commit();render();e.target.reset();$('income-error').textContent='';toast('Income included in your projection.');}catch(err){$('income-error').textContent=err.message;}};
function renderComparison(){$('comparison').innerHTML=state.snapshots.length?state.snapshots.map((s,i)=>{const r=calculate(s.plan);return `<article class="panel"><span class="eyebrow">SAVED SCENARIO ${i+1}</span><h2 style="margin-top:12px">${esc(s.name)}</h2>${line('Target age',s.plan.retire)}${line('Projected retirement',r.forecast??'Not reached')}${line('Required corpus',money(r.target))}${line('Monthly investment',money(s.plan.contribution))}${line('First shortfall',r.projection.firstShortfall??'None in horizon')}${(()=>{const l=lean(s.plan),f=fat(s.plan),b=barista(s.plan),c=coast(s.plan);return line('Lean FIRE age',l.forecast??'Not reached')+line('Fat FIRE age',f.forecast??'Not reached')+line('Barista FIRE age',b.forecast??'Not reached')+line('Coast FIRE age',!c?'—':c.reached?'Now':c.age??'Not reached');})()}<button class="button secondary" data-load="${i}">Load this plan</button><button class="danger" data-delete="${i}">Delete snapshot</button></article>`;}).join(''):'<article class="panel"><h2>Your alternatives belong here.</h2><p class="muted">Save your current plan, then explore a different retirement age or spending level.</p></article>';$('snapshot').disabled=state.snapshots.length>=5;document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>confirmAction('Load this snapshot?','This replaces your current assumptions. Save a snapshot first if you want to keep them.',()=>{state.plan=structuredClone(state.snapshots[Number(b.dataset.load)].plan);commit();renderForm();render();navigate('plan');}));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmAction('Delete this snapshot?','The current plan will remain unchanged.',()=>{state.snapshots.splice(Number(b.dataset.delete),1);commit();renderComparison();}));}
