$('export').onclick=()=>{const data=planData();const fallback=()=>{$('paste-box').open=true;$('paste-data').value=data;$('paste-data').select();toast('Your plan data is selected below. Copy it into a private note or file to keep a backup.');};try{navigator.clipboard.writeText(data).then(()=>toast('Plan data copied. Paste it into a private note or file to keep a backup.'),fallback);}catch{fallback();}};
function loadData(text,source){let next;try{if(text.length>2e6)throw Error();next=checkState(JSON.parse(text));}catch{return toast('That isn’t FIRE Planner plan data. Nothing was changed.');}confirmAction('Replace your current plan?',`Load “${next.plan.name}” from ${source}. Your current plan and snapshots will be replaced.`,()=>{state=next;openGoals.clear();commit();renderForm();render();resetFX();$('paste-data').value='';navigate('overview');toast(`Loaded “${state.plan.name}”.`);});}
$('import').onclick=()=>$('import-file').click();
$('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(file)loadData(await file.text(),file.name);};
$('paste-load').onclick=()=>{const t=$('paste-data').value.trim();if(!t)return toast('Paste your plan data into the box first.');loadData(t,'pasted data');};
$('persist').onchange=()=>{persistent=$('persist').checked;if(!persistent)try{localStorage.removeItem(KEY);}catch{toast('Could not clear storage. Clear site data in browser settings.');return;}persist();saveUI();toast(persistent?'Saved only in this browser.':'Browser saving is off. This session remains available.');};
function resetFX(){$('fx-rate').value='';$('fx-status').textContent='Enter a manual rate or fetch the latest published reference rate.';$('rate-label').firstChild.textContent=`1 ${state.currency} equals how many ${$('new-currency').value}?`;}$('new-currency').onchange=resetFX;$('fx-rate').oninput=()=>{$('fx-status').textContent='Manual exchange rate.';};
$('fetch-rate').onclick=async()=>{const from=state.currency,to=$('new-currency').value;if(from===to){$('fx-rate').value=1;return toast('Already your plan currency.');}$('fetch-rate').disabled=true;$('fx-status').textContent='Fetching a public reference rate…';try{const res=await fetch(`https://api.frankfurter.dev/v2/rate/${from.toLowerCase()}/${to.toLowerCase()}`,{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error();const data=await res.json();if(!Number.isFinite(data.rate)||data.rate<=0||!/^\d{4}-\d{2}-\d{2}$/.test(data.date))throw Error();if(from!==state.currency||to!==$('new-currency').value)return;$('fx-rate').value=data.rate;$('fx-status').textContent=`Frankfurter · Rate dated ${data.date} · Checked ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}. 1 ${from} = ${data.rate} ${to}.`;}catch{$('fx-status').textContent='Rate unavailable. Plan unchanged. Enter a manual rate or try again.';}finally{$('fetch-rate').disabled=false;}};
$('currency-form').onsubmit=e=>{e.preventDefault();const to=$('new-currency').value,rate=Number($('fx-rate').value);if(to===state.currency)return toast('Already your plan currency.');if(!Number.isFinite(rate)||rate<=0)return toast('Enter a positive exchange rate.');confirmAction('Convert your plan?',`Convert all monetary inputs, goals and snapshots from ${state.currency} to ${to} at ${rate}.`,()=>{try{const p=convertPlan(state.plan,rate),snaps=state.snapshots.map(s=>({...s,plan:convertPlan(s.plan,rate)}));validate(p);snaps.forEach(s=>validate(s.plan));state.plan=p;state.snapshots=snaps;state.currency=to;commit();renderForm();render();resetFX();toast(`Converted to ${to}.`);}catch(err){toast(err.message+' No conversion was applied.');}});};
$('print').onclick=()=>{navigate('overview');window.print();};$('reset').onclick=()=>confirmAction('Reset FIRE Planner?','Clear saved plans and snapshots and restore the sample. This cannot be undone.',()=>{try{localStorage.removeItem(KEY);}catch{return toast('Unable to clear saved data. Use browser site-data settings.');}persistent=false;state=initial();persist();renderForm();render();resetFX();navigate('overview');toast('Sample restored. Saved browser data cleared.');});
