if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_retirement_summary',description:'Read the retirement scenario calculated locally in this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments accepted.');const r=calculate(state.plan);return {currency:state.currency,targetCorpus:r.target,projectedRetirementAge:r.forecast,requiredMonthly:r.requiredMonthly,firstShortfallAge:r.projection.firstShortfall};}})).catch(()=>{});}catch{}
